#pragma once

#include <functional>

#include "cbf_safety_filter/ekf/types.hpp"

namespace ekf_estimator {

/// @brief Continuous-time dynamics, RK4 integrator and analytic Jacobian for the
/// 13-state Anafi quadrotor model.
///
/// Re-ported cleanly from legacy_controller/other/quadmodelODE.m; carries no
/// dependency on the legacy autogenerated C integrator. The roll/pitch command
/// reaches the tilt servo through a first-order lag (states uf_roll/uf_pitch),
/// so a step command moves the servo gradually rather than instantly.
class DroneModel {
 public:
  /// @brief The command issued at a given time, in seconds on the caller's clock.
  /// Answers what was *commanded* then; the model applies the delay itself.
  using InputTimeFn = std::function<InputVec(double)>;

  explicit DroneModel(const ModelParams& params);

  /// @brief Continuous-time dynamics dx/dt = f(x, u).
  /// @param x State (world-frame pos/vel, body-internal servo states; see types.hpp).
  /// @param u Control input [u_roll, u_pitch, yaw_rate, u_vel_z], already shifted
  ///   by the transport delay — i.e. what the drone is applying, not what was
  ///   just commanded.
  /// @return State time-derivative dx/dt.
  StateVec f(const StateVec& x, const InputVec& u) const;

  /// @brief Analytic Jacobian F = df/dx evaluated at (x, u); sparse (most
  /// entries zero).
  StateMat F(const StateVec& x, const InputVec& u) const;

  /// @brief One classical 4th-order Runge-Kutta step over [t0, t0 + dt], driven
  /// by a time-varying command.
  ///
  /// Each stage samples @p command at its own stage time minus
  /// params().INPUT_DELAY_SEC, so a command change landing mid-step takes effect
  /// at the right sub-step instead of being quantised to the step boundary. The
  /// two midpoint stages share one lookup, being at the same stage time.
  /// @param t0 Step start, seconds on the same clock @p command is indexed by.
  /// @param dt Step size in seconds; the caller ensures dt > 0.
  StateVec rk4Step(const StateVec& x, const InputTimeFn& command, double t0,
                   double dt) const;

  /// @brief One classical 4th-order Runge-Kutta step under a constant command.
  /// A constant signal is its own delayed copy, so this is delay-invariant.
  /// @param dt Step size in seconds; the caller ensures dt > 0.
  StateVec rk4Step(const StateVec& x, const InputVec& u, double dt) const;

  /// @brief Wrap an angle to (-pi, pi].
  static double wrapAngle(double a);

  /// @brief The model parameters this instance was constructed with.
  const ModelParams& params() const { return p_; }

 private:
  ModelParams p_;
};

}  // namespace ekf_estimator
